import csv
import json
from io import StringIO

def normalized_row(source):
    row = next(csv.DictReader(StringIO(source)), None)
    if row is None:
        raise ValueError('missing data row')
    lesson = (row.get('lesson') or '').strip()
    try:
        minutes = int(row['minutes'])
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError('minutes must be an integer') from error
    if not lesson or minutes < 0:
        raise ValueError('invalid lesson row')
    return json.dumps({'lesson': lesson, 'minutes': minutes}, sort_keys=True)
